import java.io.*;
import java.util.*;

public class C {

	BufferedReader inputReader;
	PrintWriter outputWriter;
	StringTokenizer tokens;
	boolean isEof;

	void run() throws IOException {
		nextInt();
		String s = nextToken();
		outputWriter.println(fast(s));
	}

	static final String BAD_CHARS = "VK";

	String cleanString(String s) {
		StringBuilder sb = new StringBuilder();
		for (char c : s.toCharArray()) {
			if (BAD_CHARS.indexOf(c) >= 0) {
				sb.append(c);
			} else {
				sb.append('A');
			}
		}
		return sb.toString();
	}

	int slowSolve(String s) {
		s = cleanString(s);
		Map<String, Integer> visited = new HashMap<>();
		ArrayDeque<String> queue = new ArrayDeque<>();
		queue.add(s);
		visited.put(s, 0);

		while (true) {
			String current = queue.poll();
			int dist = visited.get(current);
			if (current.indexOf(BAD_CHARS) == -1) {
				return dist;
			}
			for (int i = 0; i < current.length() - 1; i++) {
				String swapped = swapChars(current, i, i + 1);
				if (swapped != null && !visited.containsKey(swapped)) {
					visited.put(swapped, dist + 1);
					queue.add(swapped);
				}
			}
		}
	}

	String swapChars(String s, int i, int j) {
		if (s.charAt(i) == s.charAt(j)) return null;
		char[] arr = s.toCharArray();
		char tmp = arr[i];
		arr[i] = arr[j];
		arr[j] = tmp;
		return new String(arr);
	}

	static final String TARGET_STR = "VKA";

	int fast(String s) {
		s = cleanString(s);
		int len = s.length();
		int[] indices = new int[len];
		int[][] positions = new int[3][len];
		int[] sizes = new int[3];

		int[][][] countHere = new int[3][len][3];

		int[][] prefixSum = new int[len + 1][];
		prefixSum[0] = new int[] {0, 0, 0};

		for (int i = 0; i < len; i++) {
			indices[i] = TARGET_STR.indexOf(s.charAt(i));
			int cIdx = indices[i];
			countHere[cIdx][sizes[cIdx]] = prefixSum[i].clone();
			positions[cIdx][sizes[cIdx]] = i;
			sizes[cIdx]++;
			prefixSum[i + 1] = prefixSum[i].clone();
			prefixSum[i + 1][cIdx]++;
		}

		int[][][][] dp = new int[2][sizes[0] + 1][sizes[1] + 1][sizes[2] + 1];
		for (int i = 0; i < 2; i++) {
			for (int j0 = 0; j0 <= sizes[0]; j0++) {
				for (int j1 = 0; j1 <= sizes[1]; j1++) {
					Arrays.fill(dp[i][j0][j1], INF);
				}
			}
		}

		int minCost = INF;
		dp[0][0][0][0] = 0;

		for (int j0 = 0; j0 <= sizes[0]; j0++) {
			for (int j1 = 0; j1 <= sizes[1]; j1++) {
				for (int j2 = 0; j2 <= sizes[2]; j2++) {
					for (int last = 0; last < 2; last++) {
						int totalIdx = j0 + j1 + j2;
						int current = dp[last][j0][j1][j2];
						if (current == INF) continue;
						if (totalIdx == len) {
							minCost = Math.min(minCost, current);
							continue;
						}
						if (j0 < sizes[0]) {
							int cost = Math.max(j1 - countHere[0][j0][1], 0)
									+ Math.max(j2 - countHere[0][j0][2], 0);
							dp[1][j0 + 1][j1][j2] = Math.min(dp[1][j0 + 1][j1][j2], current + cost);
						}
						if (j1 < sizes[1] && last == 0) {
							int cost = Math.max(j0 - countHere[1][j1][0], 0)
									+ Math.max(j2 - countHere[1][j1][2], 0);
							dp[0][j0][j1 + 1][j2] = Math.min(dp[0][j0][j1 + 1][j2], current + cost);
						}
						if (j2 < sizes[2]) {
							int cost = Math.max(j0 - countHere[2][j2][0], 0)
									+ Math.max(j1 - countHere[2][j2][1], 0);
							dp[0][j0][j1][j2 + 1] = Math.min(dp[0][j0][j1][j2 + 1], current + cost);
						}
					}
				}
			}
		}
		return minCost;
	}

	static final int INF = 1_000_000;

	String generateSample() {
		Random rand = new Random(456);
		int n = 8;
		char[] buf = new char[n];
		for (int i = 0; i < n; i++) {
			buf[i] = TARGET_STR.charAt(rand.nextInt(3));
		}
		return new String(buf);
	}

	void performStressTest() {
		Random rand = new Random(456);
		for (int t = 0;; t++) {
			String s = generateSample();
			int fastRes = fast(s);
			int slowRes = slowSolve(s);
			if (fastRes != slowRes) {
				System.err.println("Mismatch on: " + s);
				System.err.println("Fast: " + fastRes);
				System.err.println("Slow: " + slowRes);
				throw new AssertionError();
			}
			System.err.println("Iteration: " + t);
		}
	}

	C() throws IOException {
		inputReader = new BufferedReader(new InputStreamReader(System.in));
		outputWriter = new PrintWriter(System.out);
		run();
		// performStressTest();
		outputWriter.close();
	}

	public static void main(String[] args) throws IOException {
		new C();
	}

	String next() {
		while (tokens == null || !tokens.hasMoreTokens()) {
			try {
				tokens = new StringTokenizer(inputReader.readLine());
			} catch (Exception e) {
				isEof = true;
				return null;
			}
		}
		return tokens.nextToken();
	}

	String readLine() {
		try {
			return inputReader.readLine();
		} catch (IOException e) {
			isEof = true;
			return null;
		}
	}

	int getNextInt() throws IOException {
		return Integer.parseInt(next());
	}

	long getNextLong() throws IOException {
		return Long.parseLong(next());
	}

	double getNextDouble() throws IOException {
		return Double.parseDouble(next());
	}
}
